package com.example.starter.hazmat.domain;

/**
 * 运单途经点状态：PENDING 待打卡；CHECKED 已打卡；TIMEOUT 超时未打卡（偏离预警）；
 * CANCELLED 改线生效时原路线剩余途经点终止。
 */
public enum WaypointStatus {
    PENDING,
    CHECKED,
    TIMEOUT,
    CANCELLED
}

package com.example.starter.hazmat.domain;

/**
 * 告警类型：DEVIATION 偏离预警（途经点超时未打卡）；LOST 失联（连续 2 点超时）；
 * ORDER_VIOLATION 打卡逆序拒绝；LATE_AFTER_CLOSE 结案后迟到打卡。
 */
public enum AlertType {
    DEVIATION,
    LOST,
    ORDER_VIOLATION,
    LATE_AFTER_CLOSE
}

package com.example.starter.hazmat.domain;

/**
 * 打卡结果：ACCEPTED 正常受理；LATE_AFTER_CLOSE 结案后迟到，仅记录迟到事件。
 */
public enum CheckinResult {
    ACCEPTED,
    LATE_AFTER_CLOSE
}

package com.example.starter.hazmat.domain;

/**
 * 改线申请状态：PENDING 待核准（原路线打卡继续有效）；APPROVED 已核准并原子切换；
 * REJECTED 已拒绝。
 */
public enum RerouteStatus {
    PENDING,
    APPROVED,
    REJECTED
}

