package com.example.starter.hazmat.repo;

import com.example.starter.hazmat.domain.WaypointStatus;
import com.example.starter.hazmat.model.WaybillWaypoint;
import java.sql.ResultSet;
import java.sql.SQLException;
import java.sql.Timestamp;
import java.time.LocalDateTime;
import java.util.List;
import java.util.Optional;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.stereotype.Repository;

/**
 * 运单途经点实例仓储。
 */
@Repository
public class WaybillWaypointRepository {

    private static final RowMapper<WaybillWaypoint> MAPPER = WaybillWaypointRepository::map;

    private final JdbcTemplate jdbc;

    public WaybillWaypointRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    private static WaybillWaypoint map(ResultSet rs, int i) throws SQLException {
        Timestamp checkin = rs.getTimestamp("checkin_time");
        return new WaybillWaypoint(
                rs.getLong("id"),
                rs.getLong("waybill_id"),
                rs.getInt("seq"),
                rs.getTimestamp("planned_pass_time").toLocalDateTime(),
                checkin == null ? null : checkin.toLocalDateTime(),
                WaypointStatus.valueOf(rs.getString("status")));
    }

    public void insert(long waybillId, int seq, LocalDateTime plannedPassTime) {
        jdbc.update(
                "INSERT INTO waybill_waypoint (waybill_id, seq, planned_pass_time, status)"
                        + " VALUES (?, ?, ?, 'PENDING')",
                waybillId, seq, Timestamp.valueOf(plannedPassTime));
    }

    public List<WaybillWaypoint> findByWaybill(long waybillId) {
        return jdbc.query(
                "SELECT * FROM waybill_waypoint WHERE waybill_id = ? ORDER BY seq",
                MAPPER, waybillId);
    }

    public Optional<WaybillWaypoint> findByWaybillAndSeq(long waybillId, int seq) {
        List<WaybillWaypoint> rows = jdbc.query(
                "SELECT * FROM waybill_waypoint WHERE waybill_id = ? AND seq = ?",
                MAPPER, waybillId, seq);
        return rows.stream().findFirst();
    }

    /**
     * 打卡落位：仅当途经点仍处于 PENDING/TIMEOUT 时更新为 CHECKED，返回受影响行数。
     */
    public int markChecked(long waybillId, int seq, LocalDateTime checkinTime) {
        return jdbc.update(
                "UPDATE waybill_waypoint SET status = 'CHECKED', checkin_time = ?"
                        + " WHERE waybill_id = ? AND seq = ? AND status IN ('PENDING', 'TIMEOUT')",
                Timestamp.valueOf(checkinTime), waybillId, seq);
    }

    /**
     * 超时标记：仅当途经点仍 PENDING 时更新为 TIMEOUT，返回受影响行数。
     */
    public int markTimeout(long waybillId, int seq) {
        return jdbc.update(
                "UPDATE waybill_waypoint SET status = 'TIMEOUT'"
                        + " WHERE waybill_id = ? AND seq = ? AND status = 'PENDING'",
                waybillId, seq);
    }

    /**
     * 改线生效时终止原路线未打卡途经点。
     */
    public int cancelOpenWaypoints(long waybillId) {
        return jdbc.update(
                "UPDATE waybill_waypoint SET status = 'CANCELLED'"
                        + " WHERE waybill_id = ? AND status IN ('PENDING', 'TIMEOUT')",
                waybillId);
    }
}

